    close_count = lst[0].count(')')
    open_count += lst[1].count('(')
    close_count += lst[1].count(')')

    if open_count != close_count:
        return 'No'

    concat_options = [lst[0] + lst[1], lst[1] + lst[0]]

    for option in concat_options:
        if is_balanced(option):
            return 'Yes'

    return 'No'

